class Solution:
    def countBattleships(self, board: list[list[str]]) -> int:
        count = 0
        for i in range(len(board)):                # one pass over m * n cells
            for j in range(len(board[0])):
                if board[i][j] != 'X':
                    continue
                if i > 0 and board[i - 1][j] == 'X':
                    continue                      # continuation of a vertical ship
                if j > 0 and board[i][j - 1] == 'X':
                    continue                      # continuation of a horizontal ship
                count += 1                        # top-left cell of a new ship
        return count
